    for c,n in bom[sku][revs[-1]]: expl(c,q*n,d,out)
def kits(sku,d,s):
    if sku in bom:
        s.add(sku)
        revs=[k for k in sorted(bom[sku]) if k<=d]
        for c,n in bom[sku][revs[-1]]: kits(c,d,s)
